ALTER TABLE "user"
    ADD COLUMN IF NOT EXISTS "member_expired_at" TIMESTAMPTZ DEFAULT NULL;

CREATE TABLE IF NOT EXISTS "membership_plan"
(
    "id"             BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name"           varchar(255) NOT NULL DEFAULT '',
    "description"    text         NOT NULL DEFAULT '',
    "unit_price"     int          NOT NULL DEFAULT 0,
    "duration_unit"  varchar(32)  NOT NULL DEFAULT 'Year',
    "duration_value" bigint       NOT NULL DEFAULT 1,
    "enabled"        BOOLEAN      NOT NULL DEFAULT TRUE,
    "sort"           bigint       NOT NULL DEFAULT 0,
    "created_at"     TIMESTAMPTZ           DEFAULT NULL,
    "updated_at"     TIMESTAMPTZ           DEFAULT NULL,
    PRIMARY KEY ("id")
);

INSERT INTO "membership_plan"
    ("id", "name", "description", "unit_price", "duration_unit", "duration_value", "enabled", "sort", "created_at", "updated_at")
VALUES
    (1, '年费会员', '开通后可购买订阅商品，默认有效期为一年。', 0, 'Year', 1, TRUE, 1, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

SELECT setval(pg_get_serial_sequence('membership_plan', 'id'), COALESCE((SELECT MAX("id") FROM "membership_plan"), 1), TRUE);
